use std :: sync :: Arc ; use anyhow :: { Context , Result } ; use forge_app :: { AgentRepository , DirectoryReaderInfra , EnvironmentInfra , FileInfoInfra } ; use forge_config :: ForgeConfig ; use forge_domain :: { ModelId , ProviderId , Template , ToolName } ; use gray_matter :: Matter ; use gray_matter :: engine :: YAML ; use crate :: agent_definition :: AgentDefinition ; use std :: collections :: HashMap ; use forge_domain :: AgentId ; use insta :: { assert_snapshot , assert_yaml_snapshot } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Implementation function for resolving agent ID conflicts by keeping the last"] # [doc = " occurrence. This implements the precedence order: CWD Custom > Global Custom"] # [doc = " > Built-in"] fn resolve_agent_conflicts (agents : Vec < AgentDefinition >) -> Vec < AgentDefinition > { use std :: collections :: HashMap ; let mut agent_map : HashMap < String , AgentDefinition > = HashMap :: new () ; for agent in agents { agent_map . insert (agent . id . to_string () , agent) ; } agent_map . into_values () . collect () }